            ['question' => 'Is there a dark mode?',                          'answer' => 'Fan Hub Plus is designed with a dark theme by default — easy on the eyes for late-night fandom sessions! You can toggle between dark and light mode using the moon/sun icon in the navigation bar, or set your preference permanently in your Profile settings.',                                                          'category' => 'features',    'keywords' => ['dark mode','light mode','theme','toggle']],
            ['question' => 'Where can I find merchandise?',                  'answer' => 'Visit the Merchandise Showcase section! Browse items grouped by fandom category. Look for badges like "Limited Edition", "Pre-Order", and "Collectible" for special items. Each item links to the official purchase page. We also list upcoming releases so you never miss a drop.',                                       'category' => 'merchandise', 'keywords' => ['merchandise','shop','buy','collectible','limited edition']],
            ['question' => 'How do I reset my password?',                    'answer' => 'On the login page, click "Forgot your password?". Enter your registered email address and we\'ll send you a secure reset link. The link is valid for 60 minutes. Click it, enter your new password twice, and you\'re back in. Check your spam folder if the email doesn\'t arrive.',                                   'category' => 'account',     'keywords' => ['reset password','forgot password','lost password']],
            ['question' => 'What types of multimedia are available?',        'answer' => 'The Multimedia Center features: 🎬 Trailers (official movie and anime trailers), 📹 Videos (clips, gameplay, and music videos), 🎵 Audio (podcasts and soundtracks), and 🖼️ Galleries (image collections). You can filter by media type and category.',                                                               'category' => 'content',     'keywords' => ['multimedia','video','audio','trailer','gallery']],
